UPDATE traffic_segments AS ts
SET
    geometry = ST_GeomFromGeoJSON(traced.geojson)::geography,
    support_note = CASE
        WHEN ts.support_note LIKE '%centerline-traced geometry%'
            THEN ts.support_note
        ELSE ts.support_note || ' Geometry updated to centerline-traced seed geometry for preview rendering.'
    END,
    updated_at = now()
FROM traced
WHERE ts.network_id = 'flint-downtown'
  AND ts.segment_key = traced.segment_key;
